function validate([arr, start]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 50000) return 'arr needs 1 to 5 * 10^4 values.';
  if (!arr.every(v => Number.isInteger(v) && v >= 0 && v < arr.length)) return 'Each value is between 0 and arr.length - 1.';
  if (!Number.isInteger(start) || start < 0 || start >= arr.length) return 'start is an index of arr.';
  return null;
}

