function canReach(arr, start) {
  // Grow the set of reachable indices until a full pass adds nothing new.
  const reach = new Set([start]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const i of [...reach]) {
      for (const j of [i - arr[i], i + arr[i]]) {
        if (j >= 0 && j < arr.length && !reach.has(j)) { reach.add(j); grew = true; }
      }
    }
  }
  return [...reach].some(i => arr[i] === 0);
}

