function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? 2000 : int(1, 10);
  // Short jumps make long paths; long jumps make a scattered graph.
  const span = rand() < 0.5 ? Math.min(n - 1, int(1, 4)) : n - 1;
  const arr = Array.from({ length: n }, () => Math.max(1, Math.min(n - 1, int(1, Math.max(1, span)))));
  if (n === 1) arr[0] = 0;
  // Place a handful of zeros, or sometimes none at all.
  const zeros = rand() < 0.25 ? 0 : int(1, size === 'large' ? 3 : 2);
  for (let z = 0; z < zeros; z++) arr[int(0, n - 1)] = 0;
  return [arr, int(0, n - 1)];
}
